tarefas = [
    {"titulo": "estudar Python", "concluida": True},
    {"titulo": "lavar louça", "concluida": False},
    {"titulo": "fazer exercício", "concluida": True},
    {"titulo": "ler um livro", "concluida": False}
]

print(len(tarefas))          # saida: 4
print(tarefas[0])            # saida: {'titulo': 'estudar Python', 'concluida': True}
print(tarefas[0]["titulo"])  # saida: estudar Python

tarefas = [
    {"titulo": "estudar Python", "concluida": True},
    {"titulo": "lavar louça", "concluida": False},
    {"titulo": "fazer exercício", "concluida": True},
    {"titulo": "ler um livro", "concluida": False}
]

# contando quantas tarefas estao concluidas
total_concluidas = 0
for tarefa in tarefas:
    if tarefa["concluida"]:
        total_concluidas = total_concluidas + 1
print(total_concluidas)  # saida: 2

# buscando uma tarefa pelo titulo
buscada = "lavar louça"
for tarefa in tarefas:
    if tarefa["titulo"] == buscada:
        print(f"encontrada, concluida: {tarefa['concluida']}")
# saida: encontrada, concluida: False

